diff:
--- a/rtl/sat_adder.v
+++ b/rtl/sat_adder.v
@@ -6,9 +6,12 @@
     output wire       sat
 );
-    wire [7:0] b_eff = sub ? (~b + 8'd1) : b;
-    wire [7:0] sum   = a + b_eff;
-    wire       ovf   = (a[7] == b[7]) && (sum[7] != a[7]);
+    wire signed [8:0] a_ext = {a[7], a};
+    wire signed [8:0] b_ext = {b[7], b};
+    wire signed [9:0] r     = sub ? (a_ext - b_ext) : (a_ext + b_ext);

-    assign sat = ovf;
-    assign y   = ovf ? (a[7] ? 8'h80 : 8'h7F) : sum;
+    wire gt = (r > 10'sd127);
+    wire lt = (r < -10'sd128);
+
+    assign sat = gt || lt;
+    assign y   = gt ? 8'h7F : (lt ? 8'h80 : r[7:0]);
 endmodule
